<script lang="ts">import {onMount,getContext} from 'svelte';import type {I18nState} from '../../../../../lib/i18n/i18n.svelte';import {createTransferOrdersState} from '../state/transferOrdersState.svelte';import type {CreateTransferOrder} from '../../domain/entity/TransferOrder';const i18n=getContext<I18nState>('i18n');const vm=createTransferOrdersState();let open=$state(false),source=$state(''),destination=$state(''),notes=$state(''),records=$state(''),rejectReason=$state('');onMount(()=>{void vm.load();});function parseRecords(){return records.split('\n').map(x=>x.trim()).filter(Boolean).map(x=>{const [sku,qty]=x.split(/[;,\t]/).map(y=>y.trim());return {sku,quantity:Number(qty)};}).filter(x=>x.sku&&Number.isInteger(x.quantity)&&x.quantity>0);}async function create(){const v:CreateTransferOrder={sourceWarehouseCode:source,destinationWarehouseCode:destination,notes:notes||null,records:parseRecords()};if(await vm.create(v)){open=false;source='';destination='';notes='';records='';}}async function cancel(id:number){if(confirm('¿Cancelar esta orden de traslado?'))await vm.cancel(id);}async function remove(id:number){if(confirm('¿Eliminar la orden sin actividad de picking ni aprobaciones?'))await vm.remove(id);}async function approve(id:number,a:number){if(confirm('La aprobación moverá inventario del almacén origen al destino. ¿Continuar?'))await vm.approve(id,a);}async function reject(id:number,a:number){await vm.reject(id,a,rejectReason);rejectReason='';}</script>
<section class="page"><header><div><p class="eyebrow">ABELLIS · SMART WMS</p><h1>{i18n.t('Órdenes de traslado')}</h1><p>{i18n.t('Solicita reposición entre almacenes, controla el picking y aprueba el movimiento de inventario.')}</p></div><button class="primary" onclick={()=>open=!open}>{i18n.t('Nueva orden')}</button></header>
{#if vm.error}<p class="error" role="alert">{vm.error}</p>{/if}{#if vm.created}<p class="success">{i18n.t('Orden creada')}: {vm.created.toNumber}. {i18n.t('Líneas')}: {vm.created.lineCount}. {#if vm.created.shortages.length}{i18n.t('Faltantes')}: {vm.created.shortages.map(x=>x.sku+': '+x.shortfall).join(', ')}{/if}</p>{/if}
{#if open}<form class="editor" onsubmit={e=>{e.preventDefault();void create();}}><h2>{i18n.t('Crear orden de traslado')}</h2><label>{i18n.t('Código de almacén origen')}<input required bind:value={source}/></label><label>{i18n.t('Código de almacén destino')}<input required bind:value={destination}/></label><label class="wide">{i18n.t('Notas')}<input bind:value={notes}/></label><label class="wide">{i18n.t('Líneas: un SKU y cantidad por línea (SKU, cantidad)')}<textarea rows="5" required bind:value={records} placeholder="SKU-001, 10&#10;SKU-002, 5"/></label><div class="actions"><button type="button" onclick={()=>open=false}>{i18n.t('Cancelar')}</button><button class="primary" disabled={vm.saving||parseRecords().length===0}>{i18n.t('Crear orden')}</button></div></form>{/if}
<div class="toolbar"><select value={vm.status} onchange={e=>{vm.setStatus(e.currentTarget.value);void vm.load();}}><option value="">{i18n.t('Todos los estados')}</option>{#each ['OPEN','PARTIALLY_PICKED','AWAITING_APPROVAL','APPROVED','CLOSED','CANCELLED'] as s}<option value={s}>{s}</option>{/each}</select><button onclick={()=>void vm.load()}>{i18n.t('Actualizar')}</button></div>
{#if vm.loading}<p>{i18n.t('Cargando…')}</p>{:else}<div class="table-wrap"><table><thead><tr><th>{i18n.t('Orden')}</th><th>{i18n.t('Origen')}</th><th>{i18n.t('Destino')}</th><th>{i18n.t('Estado')}</th><th>{i18n.t('Creada por')}</th><th>{i18n.t('Acciones')}</th></tr></thead><tbody>{#each vm.rows as r (r.transferOrderId)}<tr><td><button class="link" onclick={()=>void vm.detail(r.transferOrderId)}>{r.transferOrderNumber}</button></td><td>{r.sourceWarehouseId}</td><td>{r.destinationWarehouseId}</td><td>{r.status}</td><td>{r.createdBy}</td><td>{#if r.status==='OPEN'||r.status==='PARTIALLY_PICKED'}<button onclick={()=>void vm.startPicking(r.transferOrderId)}>{i18n.t('Iniciar picking')}</button><button onclick={()=>void cancel(r.transferOrderId)}>{i18n.t('Cancelar')}</button>{/if}<button onclick={()=>void remove(r.transferOrderId)}>{i18n.t('Eliminar')}</button></td></tr>{/each}</tbody></table></div>{/if}
{#if vm.selected}<aside class="detail"><div class="detail-head"><div><h2>{vm.selected.transferOrderNumber}</h2><p>{vm.selected.status} · {vm.selected.sourceWarehouseId} → {vm.selected.destinationWarehouseId}</p></div><button onclick={()=>vm.clearSelected()}>{i18n.t('Cerrar detalle')}</button></div><h3>{i18n.t('Líneas')}</h3><table><thead><tr><th>SKU</th><th>{i18n.t('Solicitado')}</th><th>{i18n.t('Comprometido')}</th><th>{i18n.t('Recogido')}</th><th>{i18n.t('Aprobado')}</th><th>{i18n.t('Estado')}</th><th>{i18n.t('Acciones')}</th></tr></thead><tbody>{#each vm.selected.lines as l (l.toLineId)}<tr><td>{l.sku??l.itemId}</td><td>{l.requestedQuantity}</td><td>{l.committedQuantity}</td><td>{l.pickedQuantity}</td><td>{l.approvedQuantity}</td><td>{l.status}</td><td>{#if l.status!=='APPROVED'&&l.status!=='SHORT_CLOSED'}<button onclick={()=>void vm.shortClose(vm.selected!.transferOrderId,l.toLineId)}>{i18n.t('Cerrar faltante')}</button>{/if}</td></tr>{/each}</tbody></table>
{#if vm.selected.status==='PARTIALLY_PICKED'||vm.selected.status==='OPEN'}<button onclick={()=>void vm.submitPicks(vm.selected!.transferOrderId)}>{i18n.t('Enviar picking para aprobación')}</button>{/if}
<h3>{i18n.t('Aprobaciones')}</h3>{#each vm.selected.approvals as a (a.approvalId)}<div class="approval"><span>#{a.approvalId} · {a.status} · {a.submittedBy}</span>{#if a.status==='PENDING'}<button class="primary" onclick={()=>void approve(vm.selected!.transferOrderId,a.approvalId)}>{i18n.t('Aprobar y mover inventario')}</button><input placeholder={i18n.t('Motivo de rechazo')} bind:value={rejectReason}/><button class="danger" onclick={()=>void reject(vm.selected!.transferOrderId,a.approvalId)}>{i18n.t('Rechazar')}</button>{/if}{#if a.rejectionReason}<p>{a.rejectionReason}</p>{/if}</div>{/each}</aside>{/if}</section>
<style>.page{max-width:78rem;margin:1.4rem auto;padding:0 1.1rem;color:var(--ink)}header,.detail-head{display:flex;justify-content:space-between;align-items:center;gap:1rem}header{margin-bottom:1rem}h1{margin:0;font:700 1.6rem var(--disp)}header p,.detail p{color:var(--slate);font-size:.9rem}.eyebrow{font:600 .65rem var(--disp);letter-spacing:.14em}button{border:1px solid var(--line);border-radius:8px;padding:.5rem .7rem;background:var(--card);color:var(--ink);cursor:pointer;margin:.15rem}.primary{background:var(--navy);color:white;border-color:var(--navy)}.danger,.error{color:var(--danger)}.success{color:var(--success)}.editor{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.7rem;padding:1rem;border:1px solid var(--line);border-radius:12px;background:var(--card)}.editor h2,.wide,.actions{grid-column:1/-1}.editor label{display:grid;gap:.3rem;color:var(--slate);font-size:.8rem}.editor input,.editor textarea,.toolbar select,.approval input{min-height:39px;border:1px solid var(--line);border-radius:8px;padding:.5rem .65rem;background:var(--card);color:var(--ink);font:inherit}.actions{display:flex;justify-content:flex-end}.toolbar{display:flex;gap:.5rem;margin:1rem 0}.table-wrap,.detail{overflow:auto;border:1px solid var(--line);border-radius:12px;background:var(--card);margin:1rem 0}.detail{padding:1rem}.approval{display:flex;align-items:center;gap:.5rem;flex-wrap:wrap;padding:.6rem 0;border-bottom:1px solid var(--line)}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:.82rem}th,td{text-align:left;padding:.65rem;border-bottom:1px solid var(--line)}th{color:var(--slate);font-size:.7rem;text-transform:uppercase}.link{border:0;background:none;color:var(--accent);text-decoration:underline}@media(max-width:640px){header{align-items:flex-start;flex-direction:column}.editor{grid-template-columns:1fr}}</style>